#[Test]
public function admin_from_different_team_gets_404(): void
{
    [$adminA, $teamA] = $this->adminWithTeam();
    [$adminB, $teamB] = $this->adminWithTeam();

    $event = $this->draftEventForTeam($teamA, $adminA);

    // AdminB's current team is teamB; TeamScopedModel global scope filters
    // the route-model binding to teamB's events only → 404.
    $response = $this->actingAs($adminB)
        ->getJson(route('events.show', $event));

    $response->assertNotFound();
}

#[Test]
public function cohost_can_view_event_on_same_team(): void
{
    [$admin, $team] = $this->adminWithTeam();
    $event = $this->draftEventForTeam($team, $admin);
    $cohost = $this->cohostOnTeam($team);

    // Cache::flush needed again since we created new users after setUp.
    Cache::flush();

    $response = $this->actingAs($cohost)
        ->getJson(route('events.show', $event));

    $response->assertOk();
    $response->assertJsonPath('data.uuid', $event->uuid);
}

#[Test]
public function billing_admin_is_denied_with_403(): void
{
    [$admin, $team] = $this->adminWithTeam();
    $event = $this->draftEventForTeam($team, $admin);
    $billing = $this->billingAdminOnTeam($team);

    Cache::flush();

    $response = $this->actingAs($billing)
